package com.bplus.share;
import android.app.*;import android.content.*;import android.os.Bundle;import android.widget.*;import org.json.*;
public class ProfileActivity extends Activity {
 private LinearLayout box;private EditText name;
 @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);build();}
 private void build(){Profile.init();LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.my_profile),true,null));ScrollView scroll=new ScrollView(this);box=Ui.col(this);Ui.pad(box,24,18,24,24,this);scroll.addView(box);root.addView(scroll,Ui.lpW1());box.addView(Profile.avatar(this,Profile.local(),96));TextView photo=Ui.ghost(this,getString(R.string.change_photo));box.addView(photo);photo.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,83);});box.addView(Ui.secHead(this,getString(R.string.display_name)));name=new EditText(this);name.setText(Store.get("profileName",Store.deviceName()));name.setTextColor(Ui.text);name.setTypeface(App.cairo);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});box.addView(name);box.addView(Ui.secHead(this,getString(R.string.username_label)));TextView handle=Ui.t(this,"@"+Store.get("username",""),22,Ui.accent,App.cairoB);box.addView(handle);handle.setOnClickListener(v->PairUi.copy(this,handle.getText().toString()));box.addView(Ui.t(this,getString(R.string.profile_privacy),13,Ui.dim,App.cairoSB));TextView save=Ui.cta(this,getString(R.string.save_profile));box.addView(save);save.setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty())return;Store.set("profileName",n);android.widget.Toast.makeText(this,getString(R.string.profile_saved),0).show();});setContentView(root);}
 @Override protected void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(q==84&&r==RESULT_OK){build();return;}if(q==83&&r==RESULT_OK&&data!=null&&data.getData()!=null){try{Store.set("profileName",name.getText().toString().trim());Intent crop=new Intent(this,CropActivity.class);crop.putExtra("uri",data.getData().toString());crop.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(crop,84);}catch(Exception e){new AlertDialog.Builder(this).setMessage(e.getMessage()).setPositiveButton(android.R.string.ok,null).show();}}}
}
